/**
 * Linear progress (spec/02 §3.12) for remote work over 1 s: [label] in text and [valueText] („60 %“) in textMuted on
 * one caption line with tabular figures, 4 dp above a 4 dp bar: [fraction] (0..1) in text on a border track from the
 * start edge, square ends, no gap and no stop dot (D85). One TalkBack node: the label as a progress bar.
 */
@Composable
fun SbProgressBar(fraction: Float, label: String, valueText: String, modifier: Modifier = Modifier) {
    val c = SebaroTheme.colors
    val t = SebaroTheme.tokens
    val ty = SebaroTheme.typography
    val share = fraction.coerceIn(0f, 1f)
    val head = ty.caption.copy(fontFeatureSettings = ty.numeric.fontFeatureSettings)
    Column(
        modifier
            .fillMaxWidth()
            .semantics(mergeDescendants = true) { progressBarRangeInfo = ProgressBarRangeInfo(share, 0f..1f) },
        verticalArrangement = Arrangement.spacedBy(t.space.s1),
    ) {
        Row(horizontalArrangement = Arrangement.spacedBy(t.space.s3)) {
            Text(label, style = head, color = c.text, modifier = Modifier.weight(1f))
            Text(valueText, style = head, color = c.textMuted, modifier = Modifier.clearAndSetSemantics { })
        }
        Canvas(Modifier.fillMaxWidth().height(t.space.s1)) {
            drawRect(c.border)
            val w = size.width * share
            val x = if (layoutDirection == LayoutDirection.Rtl) size.width - w else 0f
            drawRect(c.text, Offset(x, 0f), Size(w, size.height))
        }
    }
}

/**
 * Ring progress (spec/02 §3.12) for loading with a known share: 48 dp, a 4 dp ring on a 20 dp radius, [fraction] in
 * text clockwise from twelve o'clock on a border track, butt caps (D85), [valueText] („60 %“) in labelSmall in the
 * middle; ring and strokes grow with the text scale, and the ring grows further until the corners of the value's
 * figures keep 2 dp from its inner edge („100 %“). Not the goal ring (SbGoalRing). One TalkBack node: [label]
 * („Hochladen“) as a progress bar.
 */
@Composable
fun SbProgressRing(fraction: Float, label: String, valueText: String, modifier: Modifier = Modifier) {
    val c = SebaroTheme.colors
    val t = SebaroTheme.tokens
    val ty = SebaroTheme.typography
    val share = fraction.coerceIn(0f, 1f)
    val rem = sbTextScale()   // D99 (2): the value inside it grows with the text, so the ring does
    Layout(
        content = {
            Text(valueText, style = ty.labelSmall.copy(fontFeatureSettings = ty.numeric.fontFeatureSettings), color = c.text, maxLines = 1)
        },
        modifier = modifier
            .clearAndSetSemantics {
                contentDescription = label
                progressBarRangeInfo = ProgressBarRangeInfo(share, 0f..1f)
            }
            .drawBehind {
                val stroke = t.space.s1.toPx() * rem
                // the centre line: 20 dp in the 48 dp box, more in a box grown for its value
                val r = maxOf(t.space.s5.toPx() * rem, size.minDimension / 2 - stroke)
                drawCircle(c.border, radius = r, style = Stroke(width = stroke))
                drawArc(
                    color = c.text,
                    startAngle = -90f,
                    sweepAngle = 360f * share,
                    useCenter = false,
                    topLeft = Offset(center.x - r, center.y - r),
                    size = Size(2 * r, 2 * r),
                    style = Stroke(width = stroke, cap = StrokeCap.Butt),
                )
            },
    ) { measurables, constraints ->
        val value = measurables.first().measure(Constraints())
        // the corners of the figures (sebaro Sans: 0.71 em high, −0.011 to 0.701 em) 2 dp inside the ring's inner
        // edge; box = inner diameter + 3 strokes (48 = 2 × 18 + 3 × 4); never smaller than 48 dp × text scale
        val figures = ty.labelSmall.fontSize.toPx() * 0.72f
        val inner = hypot(value.width / 2f, figures / 2f) + (t.space.s0_5 * rem).toPx()
        val need = 2 * inner + (t.space.s1 * 3 * rem).toPx()
        val edge = maxOf((t.space.s12 * rem).roundToPx(), need.roundToInt() + 1)
        val w = edge.coerceIn(constraints.minWidth, constraints.maxWidth)
        val h = edge.coerceIn(constraints.minHeight, constraints.maxHeight)
        layout(w, h) { value.place(Alignment.Center.align(IntSize(value.width, value.height), IntSize(w, h), layoutDirection)) }
    }
}

/**
 * The spinner of spec/02 §1.7 (sb-spinner): the 20 dp loader in [tint], one turn a second, linear (a loop while remote
 * work runs, not an entry motion); still under sbReduceMotion(). Only for remote work over 1 s.
 */
@Composable
internal fun SbSpinner(tint: Color, modifier: Modifier = Modifier) {
    val t = SebaroTheme.tokens
    if (sbReduceMotion()) {
        Icon(SebaroIcons.Outline20.Loader, contentDescription = null, tint = tint, modifier = modifier.size(t.size.iconMd))
    } else {
        val turn = rememberInfiniteTransition(label = "spinner")
        val angle = turn.animateFloat(
            initialValue = 0f,
            targetValue = 360f,
            animationSpec = infiniteRepeatable(tween(1000, easing = LinearEasing)),   // the web's sb-spin 1s linear
            label = "spinner",
        )
        Icon(
            SebaroIcons.Outline20.Loader,
            contentDescription = null,
            tint = tint,
            modifier = modifier.size(t.size.iconMd).graphicsLayer { rotationZ = angle.value },
        )
    }
}
